changeSet.sql:
create function public.sicherung_export_nur_einfuegen() returns trigger
    language plpgsql as $$
    begin
        raise exception 'sicherung_export: nur Einfügen erlaubt (% verweigert)', tg_op;
    end
    $$;

create trigger sicherung_export_nur_aendern
    before update or delete on public.sicherung_export
    for each row execute function public.sicherung_export_nur_einfuegen();
create trigger sicherung_export_nicht_leeren
    before truncate on public.sicherung_export
    for each statement execute function public.sicherung_export_nur_einfuegen();

revoke all on public.sicherung_export from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'archiv_app') then
        execute 'revoke all on public.sicherung_export from archiv_app';
        execute 'grant select, insert on public.sicherung_export to archiv_app';
    end if;
end
$$;
